\label{lemma:caracterization-epsilon-close-orbit}
Given $\varepsilon > 0$ and $\xi \in \emph{\textbf{Q}}$, we have
    \begin{equation}
         \bigotimes_{i \in \mathbb{Z}}\;\; ([\xi_i - \varepsilon/3, \xi_i + \varepsilon/3] \cap [0, 1]) \subset \Gamma_\varepsilon(\xi) \subset \bigotimes_{i \in \mathbb{Z}}\;\; ([\xi_i - \varepsilon, \xi_i + \varepsilon] \cap [0, 1]).
    \end{equation}

Consider $\eta \in \bigotimes_{i \in \mathbb{Z}}\;\; ([\xi_i - \varepsilon/3, \xi_i + \varepsilon/3] \cap [0, 1])$, then $\varepsilon/3 \geq \left\lvert \eta_i - \xi_i \right\rvert$ for all $i \in \mathbb{Z}$. For any $k \in \mathbb{Z}$, 
    \begin{equation*}
        \sum_{i \in \mathbb{Z}} \frac{\left\lvert \eta_{k + i} - \xi_{k + i} \right\rvert}{2^{\left\lvert i \right\rvert}} \leq \frac{\varepsilon}{3} \sum_{i \in \mathbb{Z}} \frac{1}{2^{\left\lvert i \right\rvert}} = 3 \cdot \frac{\varepsilon}{3} = \varepsilon.
    \end{equation*}
    Hence, for any $k \in \mathbb{Z}$,
    \begin{equation*}
        \rho(\sigma^k(\eta), \sigma^k(\xi)) = \sum_{i \in \mathbb{Z}} \frac{\left\lvert \eta_{k + i} - \xi_{k + i} \right\rvert}{2^{\left\lvert i \right\rvert}} \leq \varepsilon.
    \end{equation*}
    Thus, $\eta \in \Gamma_\varepsilon(\xi)$. Now, assume that $\eta \in \Gamma_\varepsilon(\xi)$. Then, for every $k \in \mathbb{Z}$, $\rho(\sigma^k(\eta), \sigma^k(\xi)) \leq \varepsilon$. In particular, for every $k \in \mathbb{Z}$, $\left\lvert \eta_{k + 0} - \xi_{k + 0} \right\rvert \leq \varepsilon$. In other words, $\left\lvert \eta_k - \xi_k \right\rvert \leq \varepsilon$. Therefore, $\eta \in \bigotimes_{i \in \mathbb{Z}}\;\; [\xi_i - \varepsilon, \xi_i + \varepsilon] \cap [0, 1]$.

The above construction can be generalized to the shift map $\sigma: X^\mathbb{Z} \to X^\mathbb{Z}$, where $(X, d)$ is a compact metric space. Indeed, for $\hat{x} = (\ldots, x_{-1}; x_0, x_1, \ldots)$ in $X^\mathbb{Z}$, modifying the metric defined in (\ref{eq:metric_hilbert_cube}) to account for the metric $d$ yields the same calculation, showing that
    \begin{equation*}
        \bigotimes_{i \in \mathbb{Z}} B_{\varepsilon/3}(x_i) \subset \Gamma_\varepsilon(\hat{x}) \subset \bigotimes_{i \in \mathbb{Z}} B_{\varepsilon}(x_i),
    \end{equation*}
    where $B_\varepsilon(x) = \{y \in X : d(x, y) < \varepsilon\}$. However, when $X$ is a finite set, for sufficiently small $\varepsilon > 0$, $\Gamma_\varepsilon(\hat{x})$ is simply the singleton set $\{\hat{x}\}$, recovering the classical notion of expansiveness.

Let $\varepsilon > 0$ satisfy $2\varepsilon < 1$. Then, for every $\xi_i \in [0,1]$, the interval $[\xi_i - \varepsilon, \xi_i + \varepsilon] \cap [0, 1]$ is a proper subset of $[0, 1]$. Moreover, $\text{Leb}([\xi_i - \varepsilon, \xi_i + \varepsilon] \cap [0, 1]) \leq 2\varepsilon$. Hence, for $\xi \in \textbf{Q}$, by Lemma \ref{lemma:caracterization-epsilon-close-orbit}, we have
\begin{equation*}
    \mathfrak{L}(\Gamma_\varepsilon(\xi)) \leq \prod\limits_{i \in \mathbb{Z}} \text{Leb}([\xi_i - \varepsilon, \xi_i + \varepsilon] \cap [0, 1]) \leq \prod_{i \in \mathbb{Z}} (2\varepsilon) = 0.
\end{equation*}
This implies that any $\varepsilon > 0$ satisfying $2\varepsilon < 1$ is an expansivity constant for the product Lebesgue measure $\mathfrak{L}$.

Let $\varphi$ be a homeomorphism of the interval $[0, 1]$, and let $0 < \varepsilon < 1$. Because $\varphi$ is a continuous function on a compact set, it is uniformly continuous. Therefore, there exists a $\delta > 0$ such that for all $x, y \in [0, 1]$, if $\left\lvert x - y \right\rvert \leq \delta$, then $\left\lvert \varphi(x) - \varphi(y) \right\rvert < \varepsilon$. Thus, for any given $z \in [0, 1]$,
\begin{equation*}
    \text{Leb}(\varphi([z - \delta/2, z + \delta/2] \cap [0, 1])) < \varepsilon.
\end{equation*}
In other words, $\nu\left(\left[z - \delta/2, z + \delta/2\right] \cap [0, 1]\right) < \varepsilon$. Consequently, for any $\xi \in \textbf{Q}$, Lemma \ref{lemma:caracterization-epsilon-close-orbit} implies that
\begin{equation*}
     \Gamma_{\delta/2}(\xi) \subset \bigotimes_{i \in \mathbb{Z}} \left([\xi_i - \delta/2, \xi_i + \delta/2] \cap [0, 1]\right).
\end{equation*}
Therefore, since $0 < \varepsilon < 1$ and $\mathfrak{N}$ is the product measure, we obtain
\begin{equation*}
    \mathfrak{N}( \Gamma_{\delta/2}(\xi)) \leq \prod_{i \in \mathbb{Z}} \nu\left([\xi_i - \delta/2, \xi_i + \delta/2] \cap [0, 1]\right) \leq \prod_{i \in \mathbb{Z}} \varepsilon = 0.
\end{equation*}

It suffices to show that every open neighborhood of a point $\xi \in \textbf{Q}$ has positive product Lebesgue measure. Because we are considering the natural topology on $\textbf{Q}$, that is, the Tychonoff topology, a basic open neighborhood of $\xi = (\ldots, \xi_{-1}; \xi_0, \xi_1, \ldots)$ is a set of the form $\bigotimes_{i \in \mathbb{Z}} V_i$, where $V_i$ is an open neighborhood of $\xi_i$ for $i$ in a finite subset $F \subset \mathbb{Z}$, and $V_i = [0, 1]$ for all $i \in \mathbb{Z} \setminus F$. Therefore,
\begin{equation*}
    \mathfrak{L}\left(\bigotimes_{i \in \mathbb{Z}} V_i\right) = \prod_{i \in \mathbb{Z}} \text{Leb}(V_i) = \prod_{i \in F} \text{Leb}(V_i) > 0. 
\end{equation*}

Given $\varepsilon > 0$, let $(\xi^{(k)})_{k \in \mathbb{Z}}$ be a $\delta$-pseudo-orbit of $\sigma$ for some $\delta > 0$. Define $\eta \in \textbf{Q}$ by $\eta_k = \xi^{(k)}_0$. We will show that $(\xi^{(k)})_{k \in \mathbb{Z}}$ is $\varepsilon$-shadowed by $\eta$. Indeed, observe that
\begin{equation*}
    \rho(\sigma^k(\eta), \xi^{(k)}) = \sum\limits_{i \in \mathbb{Z}} \frac{\left\lvert \eta_{i+k} - \xi^{(k)}_i \right\rvert}{2^{\left\lvert i \right\rvert}} = \sum\limits_{i \in \mathbb{Z}} \frac{\left\lvert \xi^{(i + k)}_0 - \xi^{(k)}_i \right\rvert}{2^{\left\lvert i \right\rvert}}.
\end{equation*}
Since $(\xi^{(k)})_{k \in \mathbb{Z}}$ is a $\delta$-pseudo-orbit, $\rho(\sigma(\xi^{(k)}), \xi^{(k + 1)}) \leq \delta$. Hence, in particular,
\begin{equation*}
    \frac{\left\lvert \xi^{(k)}_{i + 1} - \xi^{(k + 1)}_i \right\rvert}{2^{\left\lvert i \right\rvert}} \leq \delta.
\end{equation*}
That is, $\left\lvert \xi^{(k)}_{i + 1} - \xi^{(k + 1)}_i \right\rvert \leq \delta\cdot 2^{\left\lvert i \right\rvert}$ for every $i$ and $k$ in $\mathbb{Z}$. Assume, without loss of generality, that $i > 0$. Applying the triangle inequality, we obtain
\begin{equation*}
    \left\lvert \xi^{(i + k)}_0 - \xi^{(k)}_i \right\rvert \leq \sum\limits_{j = 0}^{i-1} \left\lvert \xi^{(k + i - j)}_j - \xi^{(k + i - j - 1)}_{j + 1} \right\rvert \leq \sum\limits_{j = 0}^{i-1} \delta\cdot 2^j = \delta(2^i - 1).
\end{equation*}
In general, $\left\lvert \xi^{(i + k)}_0 - \xi^{(k)}_i \right\rvert < \delta\cdot2^{\left\lvert i \right\rvert}$. Furthermore, choose $N \in \mathbb{N}$ such that
\begin{equation*}
    \sum\limits_{\left\lvert i \right\rvert > N} \frac{1}{2^{\left\lvert i \right\rvert}} < \frac{\varepsilon}{2},
\end{equation*}
and choose $\delta > 0$ such that $\delta < \frac{\varepsilon}{2(2N + 1)}$. Therefore,
\begin{equation*}
    \rho(\sigma^k(\eta), \xi^{(k)}) = \sum\limits_{i \in \mathbb{Z}} \frac{\left\lvert \xi^{(i + k)}_0 - \xi^{(k)}_i \right\rvert}{2^{\left\lvert i \right\rvert}} \leq \sum\limits_{\left\lvert i \right\rvert \leq N} \frac{\left\lvert \xi^{(i + k)}_0 - \xi^{(k)}_i \right\rvert}{2^{\left\lvert i \right\rvert}}  + \sum\limits_{\left\lvert i \right\rvert > N} \frac{1}{2^{\left\lvert i \right\rvert}} \leq \left(\sum\limits_{\left\lvert i \right\rvert \leq N} \delta\right) + \frac{\varepsilon}{2}.
\end{equation*}
Observe that $\sum_{\left\lvert i \right\rvert \leq N} \delta = (2N + 1)\delta$. Hence, by the choice of $\delta$, $\rho(\sigma^k(\eta), \xi^{(k)}) < \varepsilon$ for all $k \in \mathbb{Z}$.

Given $\mu$ an infinite entropy invariant measure of $f: X \to X$, fix $\delta > 0$ and consider $X_\delta = \{x \in X : \mu(\Gamma_{\delta}(x)) = 0\}$. By Lemma 1.20 in \cite{morales_sirvent_2013}, we only need to show that there is $\delta > 0$ such that $\mu(X_\delta) = 1$.

    Fix $x \in X$ and let $y \in f(\Gamma_{\delta}(x))$. Then there exists $y_0 \in \Gamma_{\delta}(x)$ such that $y = f(y_0)$. In particular, this implies $d(y, f(x)) \leq \delta$. Since $y = f(y_0)$ and $y_0 \in \Gamma_{\delta}(x)$, we have $y \in \Gamma_{\delta}(f(x))$. Hence, $f(\Gamma_{\delta}(x)) \subset \Gamma_{\delta}(f(x))$. In other words,
    \begin{equation*}
        \Gamma_{\delta}(x) \subset f^{-1}(\Gamma_{\delta}(f(x))).
    \end{equation*}
    Since $\mu$ is an invariant measure for $f$, we obtain
    \begin{equation*}
        \mu(\Gamma_{\delta}(x)) \leq \mu(\Gamma_{\delta}(f(x))).
    \end{equation*}
    Consequently, $x$ belongs to $X_\delta$ whenever $f(x) \in X_\delta$. That is, $f(X_\delta) \subset X_\delta$. Equivalently, $X_\delta \subset f^{-1}(X_\delta)$. Note that $\mu(X_\delta) = \mu(f^{-1}(X_\delta))$. Since $X_\delta$ is contained in $f^{-1}(X_\delta)$, we have $\mu(X_\delta \Delta f^{-1}(X_\delta)) = 0$, where $X_\delta \Delta f^{-1}(X_\delta)$ is the symmetric difference between $X_\delta$ and $f^{-1}(X_\delta)$. Since $\mu$ is an ergodic measure, then for every $\delta > 0$, $\mu(X_\delta) \in \{0, 1\}$. Hence, we only need to show that there exists $\delta > 0$ such that $\mu(X_\delta) > 0$.

    For every $\delta > 0$, define $\phi_\delta: X \to \mathbb{R}\cup\{\infty\}$ as
    \begin{equation*}
        \phi_\delta(x) = \liminf\limits_{n \to \infty} - \frac{\log \mu(B[x, n, \delta])}{2n - 1},
    \end{equation*}
    where $B[x, n, \delta] = \{y \in X : d(f^i(x), f^i(y)) \leq \delta, \text{ for } -n + 1 \leq i \leq n - 1\}$. For $m, L \in \mathbb{N}$, set $X^{m, L} = \{x \in X : \phi_{1/m}(x) > L\}$. For a fixed $L$, $X^{m, L} \subset X^{m', L}$, whenever $m \leq m'$. Hence,
    \begin{equation*}
        \{x \in X : \sup\limits_{\delta > 0} \phi_\delta(x) = \infty\} \subset \bigcup_{m \in \mathbb{N}} X^{m, L}.
    \end{equation*}
    Thus,
    \begin{equation*}
        \mu(\{x \in X : \sup\limits_{\delta > 0} \phi_\delta(x) = \infty\}) \leq \lim\limits_{m \to \infty} \mu(X^{m, L}).
    \end{equation*}
    Since $\mu$ is an ergodic invariant measure with infinite entropy, $\mu$ is non-atomic. So, the Brin--Katok theorem \cite{brin_katok_1983} implies $\mu(\{x \in X : \sup_{\delta > 0} \phi_\delta(x) = \infty\}) = 1$. Therefore, for any $L \in \mathbb{N}$, $\lim_{m \to \infty} \mu(X^{m, L}) = 1$. This implies that there exists $m_0 \in \mathbb{N}$ such that for all $m \geq m_0$, $\mu(X^{m, L}) > 0$. For $x \in X^{m, L}$, $\mu(B[x, n, 1/m]) < e^{-L(2n - 1)}$ for $n$ sufficiently large. Since $L > 0$, we get 
    \begin{equation*}
        \lim\limits_{n \to \infty} \mu(B[x, n, 1/m]) = 0.
    \end{equation*}
    Moreover, since $\Gamma_{1/m}(x) = \bigcap\limits_{n = 0}^\infty B[x, n, 1/m]$ and $B[x, n, 1/m] \subset B[x, n', 1/m]$ whenever $n \geq n'$, then
    \begin{equation*}
        \mu(\Gamma_{1/m}(x)) = \lim\limits_{n \to \infty} \mu(B[x, n, 1/m]) = 0.
    \end{equation*}
    Hence, $x \in X_{1/m}$. Therefore, for $\delta = 1/m$, we obtain $X^{m, L} \subset X_\delta$. Which implies $\mu(X_\delta) \geq \mu(X^{m, L}) > 0$.

\label{remark:product-lebesgue-measure-infinite-entropy}
    The proof that the entropy of $\mathfrak{L}$ with respect to the shift map $\sigma$ is infinite is quite elementary, so we omit it here. The main idea is to show that, for any $m \geq 2$, the full shift on $m$ symbols $\sigma_m$ is a measurable factor of $\sigma: \textbf{Q} \to \textbf{Q}$. Indeed, consider the intervals $I_i = [i/m, (i+1)/m)$ for $0 \leq i \leq m - 1$, and define $\psi_m: \textbf{Q} \to \{0, \dots, m-1\}^\mathbb{Z}$ by $(\psi_m(\xi))_n = i$ if and only if $\xi_n \in I_i$. Clearly, $\psi_m\circ\sigma = \sigma_m\circ\psi_m$, and $(\psi_m)_*\mathfrak{L}$ is the Bernoulli measure on $\{0, \dots, m-1\}^\mathbb{Z}$. Therefore, for each $m \geq 2$, 
    \begin{equation*}
        h_{\mathfrak{L}}(\sigma) \geq h_{(\psi_m)_*\mathfrak{L}}(\sigma_m) = \log m.
    \end{equation*}

Let $E \subset \textbf{Q}$ be a Borel set such that $\sigma^{-1}(E) = E$. We must show that $\mathfrak{L}(E) \in \{0, 1\}$. Consider a sequence of cylinder sets $C_n$ such that $\mathfrak{L}(E\Delta C_n) \to 0$. This implies that $\mathfrak{L}(C_n) \to \mathfrak{L}(E)$. Moreover, since each cylinder set $C_n$ is defined by coordinates with indices in $[-n, n]$, we can choose an increasing sequence of integers $(k_n)_{n \in \mathbb{N}}$ such that $k_n > 2n$. Because the coordinates are disjoint, the sets are independent under the product measure $\mathfrak{L}$, and by shift-invariance we obtain, for each $n \in \mathbb{N}$,
    \begin{equation*}
        \mathfrak{L}(C_n \cap \sigma^{-k_n}(C_n)) = \mathfrak{L}(C_n)\mathfrak{L}(\sigma^{-k_n}(C_n)) = \mathfrak{L}(C_n)^2.
    \end{equation*}
    Furthermore, observe that
    \begin{equation*}
        \mathfrak{L}(E \Delta \sigma^{-k_n}(C_n)) = \mathfrak{L}(\sigma^{-k_n}(E) \Delta \sigma^{-k_n}(C_n)) = \mathfrak{L}(E \Delta C_n),
    \end{equation*}
    by the invariance of $E$ and of $\mathfrak{L}$, which implies that $\mathfrak{L}(E\Delta\sigma^{-k_n}(C_n)) \to 0$. Thus, 
    \begin{equation*}
        \mathfrak{L}((C_n \cap \sigma^{-k_n}(C_n)) \Delta E) \to 0.
    \end{equation*}
    This implies that
    \begin{equation*}
        \mathfrak{L}(E) = \lim\limits_{n \to \infty} \mathfrak{L}(C_n \cap \sigma^{-k_n}(C_n)) = \lim\limits_{n \to \infty} \mathfrak{L}(C_n)^2 = \mathfrak{L}(E)^2.
    \end{equation*}
    Since the product Lebesgue measure $\mathfrak{L}$ is a probability measure, this forces $\mathfrak{L}(E) \in \{0, 1\}$, confirming that $\mathfrak{L}$ is an ergodic measure for the shift map.

Let $\xi_*$ denote the point in the Hilbert cube whose coordinates are all zero. That is, $\xi_* = (\ldots, 0; 0, 0, \ldots)$. Given $\varepsilon > 0$, let $\eta \in [0, \varepsilon/3]^\mathbb{Z}$ and $k \in \mathbb{Z}$. We have that $\sigma^k(\eta) = (\ldots, \eta_{k - 1}; \eta_k, \eta_{k + 1}, \ldots)$. Note that $\sigma^k(\xi_*) = \xi_*$ for all $k \in \mathbb{Z}$. Hence,
    \begin{equation*}
        \rho(\sigma^k(\eta), \xi_*) = \sum_{i \in \mathbb{Z}} \frac{\left\lvert \eta_{k + i} \right\rvert}{2^{\left\lvert i \right\rvert}} \leq \frac{\varepsilon}{3} \sum_{i \in \mathbb{Z}} \frac{1}{2^{\left\lvert i \right\rvert}} = 3 \cdot \frac{\varepsilon}{3} = \varepsilon.
    \end{equation*}
    Thus, $\eta \in \Gamma_\varepsilon(\xi_*)$, which means $[0, \varepsilon/3]^\mathbb{Z} \subset \Gamma_\varepsilon(\xi_*)$. Note that $[0, \varepsilon/3]^\mathbb{Z}$ is invariant by the shift map. Thus, by Proposition 3.3 and Theorem 4.2 in \cite{lindenstrauss_weiss_2000} implies that $\underline{\operatorname{mdim}}_M(\sigma, [0, \varepsilon/3]^\mathbb{Z}, \rho) \geq 1$. Since this holds for all sufficiently small $\varepsilon > 0$, the shift map is not lower mmd-expansive.
